import unittest

from dedupe import dedupe


class TestDedupe(unittest.TestCase):
    def test_cases(self):
        self.assertEqual(dedupe(['A', 'a', 'b']), ['A', 'b'])
        self.assertEqual(dedupe(['x', '', 'x']), ['x'])
        self.assertEqual(dedupe([]), [])


if __name__ == '__main__':
    unittest.main()
